      }
    },
    [close],
  );

  return {
    activateEntry,
    close,
    handlers: {
      onClickCapture,
      onKeyDown,
      onPointerCancel,
      onPointerDown,
      onPointerMove,
      onPointerUp,
    },
    shouldSuppressClick,
    state,
  };
}

